CREATE TRIGGER `marks_audit_trail_delete_marks` AFTER DELETE ON `marks` FOR EACH ROW BEGIN
    centre_code,
    exam_no,
    subject_code,
    paper_no,
     old_mark,
    new_mark,
    status,
    sen,
    improvised_mark,
    entered_by,
    action,
    date_entered,
    marking_centre
  ) VALUES (
    OLD.centre_code,
    OLD.exam_no,
    OLD.subject_code,
    OLD.paper_no,
     "",
    OLD.mark,
    OLD.status,
    OLD.sen,
    OLD.improvised_mark,
    OLD.entered_by,
    'DELETE',
    NOW(),  -- You may need to adjust this based on your specific database's date/time functions
    OLD.marking_centre
  );
END
$$
