DROP TABLE IF EXISTS `apportionment`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `apportionment`  AS SELECT `marks`.`id_group` AS `id`, `marks`.`centre_code` AS `school`, count(`marks`.`centre_code`) AS `script_no`, concat(`marks`.`marking_centre`,'_',`marks`.`subject_code`,'_',`marks`.`paper_no`,'_',`marks`.`belt_no`) AS `group_id`, `marks`.`subject_code` AS `subject`, `marks`.`paper_no` AS `paper`, `marks`.`sen` AS `sen`, `marks`.`belt_no` AS `belt_no`, `marks`.`marking_centre` AS `marking_centre`, max(`marks`.`entered_by`) AS `username`, max(str_to_date(`marks`.`date_entered`,'%d/%m/%Y %H:%i:%s')) AS `date_apportioned` FROM `marks` WHERE ((`marks`.`status` = '-') AND (`marks`.`marking_centre` <> 'none')) GROUP BY `marks`.`id_group`, `marks`.`centre_code`, `marks`.`subject_code`, `marks`.`paper_no`, `marks`.`sen`, `marks`.`belt_no`, `marks`.`marking_centre``marking_centre`  ;

