CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `group_apportion`  AS SELECT `apportionment`.`group_id` AS `id`, `apportionment`.`subject` AS `subject`, `apportionment`.`paper` AS `paper`, `apportionment`.`belt_no` AS `belt_no`, count(`apportionment`.`school`) AS `no_of_centres`, sum(`apportionment`.`script_no`) AS `no_of_scripts`, `apportionment`.`marking_centre` AS `marking_centre`, min(`apportionment`.`username`) AS `min(username)`, min(`apportionment`.`date_apportioned`) AS `date_created` FROM `apportionment` GROUP BY `apportionment`.`group_id`, `apportionment`.`subject`, `apportionment`.`paper`, `apportionment`.`belt_no`, `apportionment`.`marking_centre``marking_centre`  ;

